const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const teams=[['M. Verstappen','RED BULL','1'],['L. Norris','MCLAREN','4'],['C. Leclerc','FERRARI','16'],['O. Piastri','MCLAREN','81'],['G. Russell','MERCEDES','63'],['L. Hamilton','FERRARI','44'],['F. Alonso','ASTON MARTIN','14'],['C. Sainz','WILLIAMS','55'],['P. Gasly','ALPINE','10'],['Y. Tsunoda','RB','22'],['A. Albon','WILLIAMS','23'],['L. Stroll','ASTON MARTIN','18'],['E. Ocon','HAAS','31'],['N. Hülkenberg','KICK SAUBER','27'],['K. Magnussen','HAAS','20'],['D. Ricciardo','RB','3'],['S. Pérez','RED BULL','11'],['V. Bottas','KICK SAUBER','77'],['Z. Guanyu','KICK SAUBER','24'],['O. Bearman','FERRARI','38']];
const sessions=[['FRIDAY · 11:30','Free Practice 1','60 min · completed'],['FRIDAY · 15:00','Free Practice 2','60 min · completed'],['SATURDAY · 11:30','Free Practice 3','60 min · completed'],['SATURDAY · 15:00','Sprint Qualifying','SQ1 · SQ2 · SQ3'],['SATURDAY · 19:00','Sprint','19 laps'],['SUNDAY · 14:00','Qualifying','Q1 · Q2 · Q3'],['SUNDAY · 14:00','Grand Prix','58 laps · 307.471 km'],['SUNDAY · 16:00','Investigations & Appeals','Post-session']];
const circuits=[['Suzuka','Japanese Grand Prix','05. April 2026','5.807 km'],['Melbourne','Australian Grand Prix','15. März 2026','5.278 km'],['Shanghai','Chinese Grand Prix','22. März 2026','5.451 km'],['Sakhir','Bahrain Grand Prix','12. April 2026','5.412 km'],['Jeddah','Saudi Arabian Grand Prix','19. April 2026','6.174 km'],['Miami','Miami Grand Prix','03. Mai 2026','5.412 km'],['Monaco','Monaco Grand Prix','24. Mai 2026','3.337 km'],['Barcelona','Spanish Grand Prix','14. Juni 2026','4.657 km'],['Spielberg','Austrian Grand Prix','28. Juni 2026','4.318 km'],['Silverstone','British Grand Prix','05. Juli 2026','5.891 km'],['Budapest','Hungarian Grand Prix','26. Juli 2026','4.381 km'],['Spa-Francorchamps','Belgian Grand Prix','02. Aug. 2026','7.004 km'],['Zandvoort','Dutch Grand Prix','23. Aug. 2026','4.259 km'],['Monza','Italian Grand Prix','06. Sep. 2026','5.793 km'],['Madrid','Madrid Grand Prix','13. Sep. 2026','5.474 km'],['Baku','Azerbaijan Grand Prix','26. Sep. 2026','6.003 km'],['Singapore','Singapore Grand Prix','11. Okt. 2026','4.940 km'],['Austin','United States Grand Prix','25. Okt. 2026','5.513 km'],['Mexico City','Mexico City Grand Prix','01. Nov. 2026','4.304 km'],['São Paulo','São Paulo Grand Prix','08. Nov. 2026','4.309 km'],['Las Vegas','Las Vegas Grand Prix','21. Nov. 2026','6.201 km'],['Lusail','Qatar Grand Prix','29. Nov. 2026','5.419 km'],['Yas Marina','Abu Dhabi Grand Prix','06. Dez. 2026','5.281 km']];
const incidentTemplates=[
 {type:'KOLLISION',title:'Verstappen & Norris — Kurve 1',summary:'Kontakt am Scheitelpunkt von Kurve 1. Auto 1 versuchte ein spätes Manöver innen, Auto 4 blieb auf der Außenlinie. Beide Fahrzeuge fahren weiter.',article:'FIA ISC Appendix L · Ch. IV, Art. 2(d)',p:42,cp:58,pro:'Verstappen war am Kurveneingang auf Höhe; Norris ließ nicht ausreichend Platz.',con:'Spätes Bremsen führte zum Kontrollverlust. Verursacher trägt Hauptverantwortung für Kontakt.',prec:'Brasilien 2024 · Turn 4',precdesc:'Ähnliche Onboard-Situation · 10 Sek. Zeitstrafe',options:[['Keine weitere Maßnahme',22],['5 Sekunden',48],['10 Sekunden',24],['Strafpunkte',6]],recommend:'5 Sekunden',reason:'Empfehlung basiert auf Präzedenzfällen und Onboard-Telemetrie. Endgültige Entscheidung liegt bei der Rennleitung.',cam:'TV',sector:'SEKTOR 1 · T1',radio:'“He just turned in on me. I was alongside, there was nowhere to go.”'},
 {type:'TRACK LIMITS',title:'Schumacher — wiederholte Verstöße',summary:'Auto 47 hat in Runde 32 zum vierten Mal die Streckenbegrenzung in Kurve 9 überschritten. Kein dauerhafter Vorteil erkennbar, Verstöße wurden dokumentiert.',article:'FIA F1 Sporting Regulations · Art. 33.3',p:35,cp:65,pro:'Ausweichmanöver nach leichtem Übersteuern; kein Zeitgewinn gegenüber der Ideallinie.',con:'Vierter Verstoß in derselben Session. Frühere Warnungen wurden über Teamfunk zugestellt.',prec:'Österreich 2023 · Track limits',precdesc:'Wiederholte Verstöße · Schwarz-Weiß-Flagge',options:[['Keine weitere Maßnahme',12],['Schwarz-Weiß-Flagge',34],['5 Sekunden',42],['Strafpunkte',12]],recommend:'5 Sekunden',reason:'Wiederholung nach Verwarnung erhöht die Sanktion. Zeitgewinn und Streckensicherheit sind bei der Abwägung zu berücksichtigen.',cam:'TRACK CAM',sector:'SEKTOR 2 · T9',radio:'“Understood, I’ll keep it within the white lines. The rear just stepped out.”'},
 {type:'UNSAFE RELEASE',title:'Sainz — unsicheres Verlassen der Box',summary:'Auto 55 wurde aus der Box freigegeben, während Auto 10 auf der Fast Lane herannahte. Beide Fahrer mussten deutlich bremsen; es kam zu keinem Kontakt.',article:'FIA F1 Sporting Regulations · Art. 34.14',p:28,cp:72,pro:'Die Boxenampel zeigte Grün; das Team konnte die Ankunft des Alpine im toten Winkel nicht sehen.',con:'Unsichere Freigabe gefährdete Auto 10 unmittelbar. Der Teamprozess muss ankommende Fahrzeuge priorisieren.',prec:'Monaco 2022 · Pit lane release',precdesc:'Unsafe release · 5.000 € Geldstrafe',options:[['Keine weitere Maßnahme',8],['Verwarnung',14],['5 Sekunden',23],['Geldstrafe',55]],recommend:'Geldstrafe',reason:'Bei Unsafe Release liegt die Verantwortung regelmäßig beim Team. Finanzielle Sanktion und Gefährdungsgrad sind abzuwägen.',cam:'PIT LANE',sector:'PIT LANE · EXIT',radio:'“That was close! He came right across the fast lane.”'},
 {type:'ÜBERHOLMANÖVER',title:'Leclerc — Kontakt in Kurve 11',summary:'Auto 16 ging außen neben Auto 63, beide berührten sich am Scheitelpunkt. Auto 63 verließ die Strecke und verlor zwei Positionen.',article:'FIA ISC Appendix L · Ch. IV, Art. 2(d)',p:61,cp:39,pro:'Leclerc war mit der Vorderachse auf Höhe am Apex und kontrollierte das Fahrzeug vollständig.',con:'Der Überholversuch außen ließ wenig Reaktionszeit. Russell musste ausweichen und verlor Positionen.',prec:'Japan 2022 · Turn 11',precdesc:'Apex overlap berücksichtigt · Keine weitere Maßnahme',options:[['Keine weitere Maßnahme',55],['Verwarnung',25],['5 Sekunden',16],['Strafpunkte',4]],recommend:'Keine weitere Maßnahme',reason:'Beide Fahrzeuge waren am Apex auf Höhe. Kein Fahrer wurde eindeutig als überwiegend schuldhaft identifiziert.',cam:'HELICOPTER',sector:'SEKTOR 2 · T11',radio:'“He squeezed me all the way to the exit. I had to back out.”'},
 {type:'PIT SPEED',title:'Hamilton — Geschwindigkeitsüberschreitung',summary:'Auto 44 passierte die Boxenradar-Messstelle mit 82,6 km/h bei einem Limit von 80 km/h. Die Überschreitung beträgt 2,6 km/h.',article:'FIA F1 Sporting Regulations · Art. 34.7',p:18,cp:82,pro:'Mögliche Messabweichung bei nasser Sensoroberfläche; der Fahrer meldet fehlende Traktion.',con:'Kalibrierte Radarwerte liegen oberhalb der Toleranz. Der Grenzwert gilt unabhängig von den Bedingungen.',prec:'Bahrain 2024 · Pit speed limit',precdesc:'Geringe Überschreitung im Rennen · 5 Sek.',options:[['Keine weitere Maßnahme',7],['5 Sekunden',58],['10 Sekunden',20],['Drive Through',15]],recommend:'5 Sekunden',reason:'Die dokumentierte Überschreitung liegt über der Messtoleranz. Der geringe Umfang spricht für die Basissanktion.',cam:'PIT ENTRY',sector:'PIT LANE · SPEED TRAP',radio:'“I was on the limiter. Can you check the sensor? It felt like it cut out.”'},
 {type:'IGNORIERTE FLAGGE',title:'Alonso — gelbe Flagge nicht beachtet',summary:'Auto 14 setzte die schnelle Runde unter doppelt geschwenkter gelber Flagge fort und verbesserte die Sektorzeit um 0,4 Sekunden. Marshals meldeten ein liegengebliebenes Fahrzeug.',article:'FIA ISC · Appendix H, Art. 2.5.5',p:20,cp:80,pro:'Fahrer gibt an, die Flagge wegen Sprühnebel und Sichtbehinderung nicht gesehen zu haben.',con:'Deutliche Sektorverbesserung unter doppelter Gelbflagge. Besondere Vorsicht war zwingend erforderlich.',prec:'Österreich 2020 · Yellow flag',precdesc:'Zeitverbesserung unter gelb · 3 Startplätze',options:[['Keine weitere Maßnahme',5],['Verwarnung',9],['5 Sekunden',14],['Gridstrafe',72]],recommend:'Gridstrafe',reason:'Die Verbesserung der Sektorzeit unter doppelt gelber Flagge wiegt schwer. Sicherheitsverpflichtungen gelten unabhängig von Sichtbedingungen.',cam:'MARSHAL POST',sector:'SEKTOR 3 · DOPPELT GELB',radio:'“I didn’t see the yellow until the last moment. The spray was terrible.”'}
];
const rules=[['Art. 33.3','Streckenbegrenzung','Fahrer müssen die Strecke jederzeit nutzen. Das Verlassen der Strecke ohne gerechtfertigten Grund kann einen dauerhaften Vorteil oder Zeitgewinn darstellen. Wiederholte Verstöße können zu einer Schwarz-Weiß-Flagge und danach zu einer Strafe führen.','Sporting'],['Art. 34.7','Geschwindigkeitsbegrenzung in der Boxengasse','Das Boxengassenlimit wird je Veranstaltung festgelegt und im Event Supplementary Regulations veröffentlicht. Überschreitungen werden nach Höhe und Session mit Geld- oder Zeitstrafen geahndet.','Sporting'],['Art. 34.14','Unsichere Freigabe (Unsafe Release)','Teams dürfen ein Fahrzeug nur sicher in die Fast Lane entlassen. Bei unsicherer Freigabe kann eine Geldstrafe oder Sportstrafe gegen Fahrer und/oder Team verhängt werden.','Sporting'],['Art. 54','Strafen','Die Stewards können Verwarnungen, Zeitstrafen, Drive-through, Stop-and-go, Gridstrafen, Strafpunkte, Geldstrafen, Disqualifikation oder Suspendierung verhängen.','Sporting'],['Appendix L · Ch. IV, Art. 2(d)','Fahrverhalten und Überholen','Manöver müssen unter Kontrolle und sicher durchgeführt werden. Bei der Beurteilung einer Kollision sind unter anderem Überlappung am Apex, Kontrolle des Fahrzeugs und vermeidbares Verhalten zu berücksichtigen.','International Sporting Code'],['Appendix H · Art. 2.5.5','Flaggensignale','Gelbe Flaggen signalisieren Gefahr. Bei doppelt geschwenkter gelber Flagge müssen Fahrer deutlich verlangsamen und bereit sein, anzuhalten oder die Richtung zu ändern. Überholen ist untersagt.','International Sporting Code'],['Art. 28','Fahrzeugkonformität','Jedes Fahrzeug muss während des Wettbewerbs jederzeit den technischen Anforderungen entsprechen. Die Verantwortung für Konformität liegt bei Teilnehmer und Team.','Technical'],['Art. 30','Kraftstoff','Kraftstoffproben müssen nach der Session verfügbar sein. Die geforderte Mindestmenge muss den Stewards auf Anfrage zugänglich gemacht werden.','Technical'],['Art. 40','Reifen','Die von der FIA zugewiesenen Reifen müssen entsprechend der Vorschriften verwendet und erfasst werden. Reifenwechsel und Zuteilung sind durch das technische Reglement geregelt.','Technical'],['Art. 37','Parc Fermé','Nach Beginn der Qualifikation gelten Einschränkungen an Fahrzeugen. Nicht autorisierte Änderungen können zu einem Start aus der Boxengasse oder weiteren Sanktionen führen.','Technical'],['Art. 55','Safety Car','Das Safety Car kann bei unmittelbarer Gefahr auf oder neben der Strecke eingesetzt werden. Fahrer müssen sich an Delta- und Abstandsregeln halten, bis das Safety Car zurückgerufen wird.','Race Control'],['Art. 57','Rennunterbrechung','Bei Abbruch wird rote Flagge gezeigt. Fahrer müssen die Anweisungen befolgen und sich in der vorgegebenen Reihenfolge in der Boxengasse aufstellen.','Race Control']];
let incidentIndex=0, currentSession=6, selectedCircuit=0, weather=0, decisions=JSON.parse(localStorage.getItem('rc-decisions')||'[]'), difficulty=localStorage.getItem('rc-difficulty')||'PROFI', controls={}, currentIncident=incidentTemplates[0], raceClock=84*60+38, replayPlaying=false, currentCam='TV';
function toast(msg){$('#toastText').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2400)}
function setView(name){$$('.view').forEach(v=>v.classList.remove('active'));$('#'+name+'View').classList.add('active');$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===name));$('#topSession').textContent=name==='race'?'RACE CONTROL':name==='weekend'?'RACE WEEKEND':name==='stats'?'SEASON STATISTICS':'FIA RULEBOOK';if(name==='stats')renderStats();if(name==='weekend')renderSessions()}
function renderTiming(){const gaps=['LEADER','+ 2.481','+ 5.906','+ 8.112','+ 12.775'];$('#timingList').innerHTML=teams.slice(0,5).map((t,i)=>`<div class="timing-row"><span class="timing-pos">${String(i+1).padStart(2,'0')}</span><span class="timing-driver">${t[0]}</span><span class="timing-team">${t[1]}</span><span class="timing-gap">${gaps[i]}</span></div>`).join('')}
function setIncident(data,index){currentIncident=data;incidentIndex=index;$('#incidentNumber').textContent='#'+String(47+index).padStart(4,'0');$('#incidentType').textContent=data.type;$('#incidentTitle').textContent=data.title;$('#incidentSummary').textContent=data.summary;$('#ruleArticle').textContent=data.article;$('#proPercent').textContent=data.p+'%';$('#conPercent').textContent=data.cp+'%';$('#proText').textContent=data.pro;$('#conText').textContent=data.con;$('#precedentTitle').textContent=data.prec;$('#precedentDesc').textContent=data.precdesc;$('#decisionReason').textContent=data.reason;$('.sector-pill').innerHTML='📍 '+data.sector;$('#replayCaption').innerHTML='<span class="red-pip"></span> 14:32:07.412 <b>'+data.type.toLowerCase()+' · replay synced</b>';$('#radioText').textContent=data.radio;$('#camBtn').textContent=data.cam+' CAM⌄';$('#incidentStatus').textContent='UNTERSUCHUNG';$('#incidentStatus').style.color='';$('#incidentStatus').style.borderColor='';$('#incidentStatus').style.background='';$('#probabilityList').innerHTML=data.options.map((o,i)=>`<div class="prob-row ${o[0]===data.recommend?'favored':''}" style="animation-delay:${i*.05}s"><span>${o[0]}</span><div class="prob-track"><i style="width:${o[1]}%"></i></div><b>${String(o[1]).padStart(2,'0')}%</b></div>`).join('');$('#driver1').textContent=data.title.split('—')[0].trim();$('#driver2').textContent=data.type==='UNSAFE RELEASE'?'P. Gasly':data.type==='TRACK LIMITS'?'R. Hülkenberg':data.type==='PIT SPEED'?'L. Norris':data.type==='IGNORIERTE FLAGGE'?'C. Sainz':'G. Russell';$('#team1').textContent=data.type==='UNSAFE RELEASE'?'WILLIAMS':data.type==='TRACK LIMITS'?'HAAS':data.type==='PIT SPEED'?'FERRARI':data.type==='IGNORIERTE FLAGGE'?'ASTON MARTIN':'RED BULL RACING';$('#team2').textContent=data.type==='UNSAFE RELEASE'?'ALPINE':'MERCEDES';$('#driverNo1').textContent=data.type==='UNSAFE RELEASE'?'55':data.type==='TRACK LIMITS'?'47':data.type==='PIT SPEED'?'44':data.type==='IGNORIERTE FLAGGE'?'14':'1';$('#driverNo2').textContent=data.type==='UNSAFE RELEASE'?'10':data.type==='TRACK LIMITS'?'27':data.type==='PIT SPEED'?'4':data.type==='IGNORIERTE FLAGGE'?'55':'63';$$('.queue-item').forEach((el,i)=>el.classList.toggle('selected',i===index%3));}
function nextIncident(){let n;do{n=Math.floor(Math.random()*incidentTemplates.length)}while(incidentTemplates.length>1&&n===incidentIndex);setIncident(incidentTemplates[n],n);toast('Neuer Vorfall in der Incident Queue')}
function openModal(title,body,actions=''){const m=$('#modal');m.innerHTML=`<div class="modal-head"><h2>${title}</h2><button class="modal-close" aria-label="Schließen">×</button></div>${body}${actions}`;$('#modalBackdrop').classList.add('open');$('.modal-close').onclick=closeModal;$('#modalBackdrop').onclick=e=>{if(e.target.id==='modalBackdrop')closeModal()}}
function closeModal(){$('#modalBackdrop').classList.remove('open')}
function openDecision(){const opts=currentIncident.options.map(o=>`<button class="decision-option" data-decision="${o[0]}"><b>${o[0]}</b><small>KI-Wahrscheinlichkeit ${o[1]}% · ${o[0]===currentIncident.recommend?'Steward-Empfehlung':''}</small></button>`).join('');openModal('Endgültige Entscheidung',`<p><b>${currentIncident.type} — ${currentIncident.title}</b><br>Prüfen Sie Beweislage, anwendbaren Artikel und Präzedenzfälle. Ihre Wahl wird in der Saisonstatistik erfasst.</p><div class="decision-options">${opts}</div>`);$$('[data-decision]').forEach(b=>b.onclick=()=>{const d=b.dataset.decision,correct=d===currentIncident.recommend;decisions.push({decision:d,correct,time:Math.floor(25+Math.random()*90),incident:currentIncident.type,date:new Date().toISOString()});localStorage.setItem('rc-decisions',JSON.stringify(decisions));closeModal();$('#incidentStatus').textContent=d.toUpperCase();$('#incidentStatus').style.color=correct?'#b9f36b':'#ff8588';$('#incidentStatus').style.borderColor=correct?'#607c48':'#854348';$('#incidentStatus').style.background=correct?'#202d20':'#332022';toast(correct?'Entscheidung gespeichert · Gute Begründung!':'Entscheidung gespeichert · Präzedenzfall notiert');});}
function renderSessions(){const completed=decisions.length>0;$('#sessionsGrid').innerHTML=sessions.map((s,i)=>`<div class="session-card ${i<5?'completed':''} ${i===currentSession?'current':''}" data-session="${i}"><span class="session-day">${s[0]}</span><span class="session-state">${i===currentSession?'LIVE':i<5?'✓ ABGESCHLOSSEN':'GEPLANT'}</span><h3>${s[1]}</h3><p>${s[2]}</p></div>`).join('');$$('.session-card').forEach(c=>c.onclick=()=>{currentSession=+c.dataset.session;$('#stageName').textContent=sessions[currentSession][1].toUpperCase();$('#sessionTag').textContent=sessions[currentSession][1].toUpperCase()+' · SESSION ACTIVE';toast(sessions[currentSession][1]+' gestartet');renderSessions();setView('race')})}
function renderStats(){let n=decisions.length,correct=decisions.filter(x=>x.correct).length,acc=n?Math.round(correct/n*100):0,avg=n?Math.round(decisions.reduce((a,x)=>a+x.time,0)/n):0;$('#statsCards').innerHTML=`<div class="stat-card"><small>ENTSCHEIDUNGEN</small><b>${n}<span> gesamt</span></b><em>SAISON 2026</em></div><div class="stat-card"><small>GENAUIGKEIT</small><b>${acc}<span>%</span></b><em>${correct} richtige Urteile</em></div><div class="stat-card"><small>Ø ENTSCHEIDUNGSZEIT</small><b>${avg||'—'}<span> sek.</span></b><em>pro Vorfall</em></div><div class="stat-card"><small>STRAFPUNKTE VERGEBEN</small><b>${decisions.filter(d=>d.decision==='Strafpunkte').length}<span> pts</span></b><em>aktuelle Saison</em></div>`;let counts={};decisions.forEach(d=>counts[d.decision]=(counts[d.decision]||0)+1);const penalties=Object.entries(counts).length?Object.entries(counts):[['Keine weitere Maßnahme',0],['Verwarnung',0],['5 Sekunden',0],['10 Sekunden',0],['Strafpunkte',0]];$('#penaltyChart').innerHTML=penalties.slice(0,7).map(([k,v])=>`<div class="penalty-col"><div class="penalty-bar" style="height:${Math.max(3,Math.min(90,v*25))}%"><span>${v}</span></div><small>${k.length>13?k.slice(0,12)+'…':k}</small></div>`).join('');$('#seasonRaces').innerHTML=circuits.slice(0,6).map((c,i)=>`<div class="season-race"><span class="race-round">${String(i+1).padStart(2,'0')}</span><span class="race-flag">${['🇦🇺','🇨🇳','🇯🇵','🇧🇭','🇸🇦','🇺🇸'][i]}</span><b>${c[1]}</b><small>${c[2].split(' ').slice(0,2).join(' ')}</small></div>`).join('')}
function renderRules(category='Allgemein',query=''){const filtered=rules.filter(r=>(category==='Allgemein'||r[3]===category)&&(!query||r.join(' ').toLowerCase().includes(query.toLowerCase())));$('#ruleList').innerHTML=filtered.length?filtered.map(r=>`<article class="rule-entry"><div class="rule-entry-head"><span class="rule-num">${r[0]}</span><h3>${r[1]}</h3><span class="rule-category-label">${r[3].toUpperCase()}</span></div><p>${r[2]}</p></article>`).join(''):'<p>Keine passenden Artikel gefunden.</p>'}
function initRules(){const cats=['Allgemein','Sporting','International Sporting Code','Technical','Race Control'];$('#ruleCategories').innerHTML=cats.map((c,i)=>`<button class="rule-category ${i===0?'active':''}" data-category="${c}">${c}</button>`).join('');$$('.rule-category').forEach(b=>b.onclick=()=>{$$('.rule-category').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderRules(b.dataset.category,$('#ruleSearch').value)});$('#ruleSearch').oninput=()=>renderRules($('.rule-category.active').dataset.category,$('#ruleSearch').value);renderRules()}
function openTrackPicker(){openModal('Strecke auswählen',`<p>Wähle eine Strecke für dein Rennwochenende. Saisonkalender 2026 · ${circuits.length} Grand Prix.</p><div class="form-field"><label>FIA KALENDER</label><select id="circuitSelect">${circuits.map((c,i)=>`<option value="${i}" ${i===selectedCircuit?'selected':''}>${String(i+1).padStart(2,'0')} · ${c[1]} — ${c[0]}</option>`).join('')}</select></div>`,`<div class="modal-actions"><button class="btn btn-ghost modal-close">Abbrechen</button><button class="btn btn-primary" id="selectCircuit">Strecke laden →</button></div>`);$('#selectCircuit').onclick=()=>{selectedCircuit=+$('#circuitSelect').value;updateCircuit();closeModal();toast(circuits[selectedCircuit][0]+' geladen')};}
function updateCircuit(){let c=circuits[selectedCircuit];$('#circuitName').textContent=c[0];$('#dateLine').textContent=c[1]+' · '+c[2];}
function createTrack(){openModal('Eigene Strecke anlegen',`<p>Erstelle ein benutzerdefiniertes Event. Eigene Strecken werden lokal auf diesem Gerät gespeichert.</p><div class="form-grid"><label class="form-field">STRECKENNAME<input id="trackName" placeholder="z. B. Alpine Ring"></label><label class="form-field">GRAND PRIX<input id="gpName" placeholder="z. B. Alpine Grand Prix"></label><label class="form-field">STRECKENLÄNGE (KM)<input id="trackLength" type="number" min="1" step="0.001" placeholder="5.000"></label><label class="form-field">RUNDE<input id="trackLaps" type="number" min="1" placeholder="58"></label><label class="form-field full">BESONDERHEITEN<textarea id="trackNotes" placeholder="Kurven, DRS-Zonen, Gefahrenstellen …"></textarea></label></div>`,`<div class="modal-actions"><button class="btn btn-ghost modal-close">Abbrechen</button><button class="btn btn-primary" id="saveTrack">Strecke speichern</button></div>`);$('#saveTrack').onclick=()=>{const name=$('#trackName').value.trim(),gp=$('#gpName').value.trim(),km=$('#trackLength').value;if(!name||!gp||!km){toast('Bitte Pflichtfelder ausfüllen');return}const custom=JSON.parse(localStorage.getItem('rc-custom-tracks')||'[]');custom.push({name,gp,date:'Eigene Strecke',km:km+' km',laps:$('#trackLaps').value,notes:$('#trackNotes').value});localStorage.setItem('rc-custom-tracks',JSON.stringify(custom));circuits.push([name,gp,'Eigene Strecke',km+' km']);selectedCircuit=circuits.length-1;updateCircuit();closeModal();toast('Eigene Strecke gespeichert')};}
